let users = [
  { id: 1, username: 'testuser', password: 'password123', email: 'test@example.com' },
  { id: 2, username: 'john', password: 'john123', email: 'john@example.com' }
];

let nextId = 3;

// Helper function to simulate API delay
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));




// Get all users
export const getUsers = async () => {
  try {
    // For real API: const response = await fetch('/api/users');
    // return await response.json();
    
    await delay(500); // Simulate network delay
    return [...users]; // Return a copy to avoid mutation
  } catch (error) {
    throw new Error('Failed to fetch users: ' + error.message);
  }
};

// Get user by ID
export const getUserById = async (id) => {
  try {
    // For real API: const response = await fetch(`/api/users/${id}`);
    // return await response.json();
    
    await delay(300);
    const user = users.find(u => u.id === id);
    if (!user) throw new Error('User not found');
    return { ...user }; // Return a copy
  } catch (error) {
    throw new Error('Failed to fetch user: ' + error.message);
  }
};

// Alias for getUserById (to handle the typo in your error message)
export const getUserByID = async (id) => {
  return getUserById(id);
};

// Get user by username
export const getUser = async (username) => {
  try {
    // For real API: const response = await fetch(`/api/users?username=${username}`);
    // const users = await response.json();
    // return users[0];
    
    await delay(300);
    const user = users.find(u => u.username === username);
    return user ? { ...user } : null; // Return copy or null if not found
  } catch (error) {
    throw new Error('Failed to fetch user: ' + error.message);
  }
};

// Create new user
export const createUser = async (userData) => {
  try {
    // For real API: const response = await fetch('/api/users', {
    //   method: 'POST',
    //   headers: { 'Content-Type': 'application/json' },
    //   body: JSON.stringify(userData)
    // });
    // return await response.json();
    
    await delay(500);
    
    // Check if user already exists
    const existingUser = users.find(u => u.username === userData.username);
    if (existingUser) {
      throw new Error('Username already exists');
    }
    
    const newUser = {
      id: nextId++,
      username: userData.username,
      password: userData.password,
      email: userData.email || '',
      createdAt: new Date().toISOString()
    };
    
    users.push(newUser);
    return { ...newUser }; // Return copy without exposing internal array
  } catch (error) {
    throw new Error('Failed to create user: ' + error.message);
  }
